<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('reports.export');$type=$_GET['type']??'units';$queries=['units'=>'SELECT unit_code Kode,unit_name Unit,category Kategori,location Lokasi,current_meter Meter,operational_status Status FROM units ORDER BY unit_code','service'=>"SELECT u.unit_code Unit,u.current_meter Meter,ss.next_service_meter Target,ss.next_service_date Tanggal,ss.status Status FROM service_schedules ss JOIN units u ON u.id=ss.unit_id ORDER BY ss.next_service_date",'analytics'=>"SELECT u.unit_code Unit,u.location Lokasi,u.current_meter Meter,COALESCE(SUM(m.actual_cost),0) Biaya FROM units u LEFT JOIN maintenance_orders m ON m.unit_id=u.id GROUP BY u.id"];$sql=$queries[$type]??$queries['units'];$rows=$pdo->query($sql)->fetchAll();audit($pdo,'EXPORT','report',null,'PDF '.$type);?><!doctype html><html><head><meta charset="utf-8"><title>Laporan AssetPro</title><style>body{font-family:Arial;margin:25px}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #aaa;padding:7px}h1{font-size:20px}.no-print{margin-bottom:15px}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="window.print()">Cetak / Simpan PDF</button><h1>Laporan <?=e(ucfirst($type))?> AssetPro</h1><p>Dicetak <?=date('d-m-Y H:i')?></p><table><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e($h)?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></body></html>
